package markdown

import (
	"fmt"
	"strings"
)

// Render converts a markdown document to HTML.
//
// Refactoring notes: the original implementation scanned the document one
// character at a time while juggling several pieces of global state (header
// level, a "header ended" flag, list counters, ...). The rewrite works line
// by line instead: emphasis markers are resolved up front, and each line is
// rendered as a header, a list item, or paragraph text.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if level, text, ok := parseHeader(line); ok {
			closeList(&html, &inList)
			if level == 7 {
				// More than six hashes is not a header; keep the hashes as literal text.
				html.WriteString("<p>" + strings.Repeat("#", level) + " " + text + "</p>")
			} else {
				html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", level, text, level))
			}
			continue
		}

		if strings.HasPrefix(line, "* ") {
			if inList {
				html.WriteString("<li>")
			} else {
				html.WriteString("<ul><li>")
				inList = true
			}
			html.WriteString(line[len("* "):])
			continue
		}

		closeList(&html, &inList)
		html.WriteString("<p>" + line + "</p>")
	}

	closeList(&html, &inList)
	return html.String()
}

// parseHeader reports whether line begins a header. It returns the header
// level (the number of leading '#' characters) and the header text, which
// starts after the space that follows the hashes.
func parseHeader(line string) (level int, text string, ok bool) {
	if !strings.HasPrefix(line, "#") {
		return 0, "", false
	}
	for i := 0; i < len(line) && line[i] == '#'; i++ {
		level = i + 1
	}
	if level < len(line) {
		text = line[level+1:] // skip the space after the hashes
	}
	return level, text, true
}

// closeList ends the current list item and list, if one is open.
func closeList(html *strings.Builder, inList *bool) {
	if *inList {
		html.WriteString("</li></ul>")
		*inList = false
	}
}

// applyEmphasis converts the first __...__ pair to <strong> and the first
// _..._ pair to <em>, matching the original implementation.
func applyEmphasis(markdown string) string {
	markdown = wrapFirstPair(markdown, "__", "<strong>", "</strong>")
	return wrapFirstPair(markdown, "_", "<em>", "</em>")
}

// wrapFirstPair wraps the text between the first two occurrences of marker
// in open and close tags. If marker appears fewer than twice, s is returned
// unchanged.
func wrapFirstPair(s, marker, open, close string) string {
	start := strings.Index(s, marker)
	if start < 0 {
		return s
	}
	end := strings.Index(s[start+len(marker):], marker)
	if end < 0 {
		return s
	}
	end += start + len(marker)
	return s[:start] + open + s[start+len(marker):end] + close + s[end+len(marker):]
}

